    ]
  },
  {
    "alert_id": "ALERT_MONITORING_GAP_003",
    "title": "Missing LFTs and renal monitoring on TDF",
    "message": "Guidelines state that for TDF-related adverse events, LFTs and RFTs should be performed. No liver function tests are documented today, and no renal function trend is available beyond a single creatinine. Serum phosphate was measured but not acted upon. The plan to review in 6 months without further renal or hepatic monitoring is insufficient given the abnormal phosphate and proteinuria findings.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Order LFTs and repeat RFTs including phosphate and urinalysis. Do not defer renal monitoring for 6 months given current abnormalities.",
    "citations": [
